package sepoa.svc.cbo.seal.postprocess;

import java.awt.image.BufferedImage;
import java.io.File;
import java.util.HashMap;
import java.util.Map;
import java.util.Map.Entry;

import org.apache.commons.collections.MapUtils;
import org.apache.commons.io.FileUtils;
import org.apache.pdfbox.pdmodel.PDDocument;
import org.apache.pdfbox.pdmodel.PDPage;
import org.apache.pdfbox.pdmodel.PDPageContentStream;
import org.apache.pdfbox.pdmodel.common.PDRectangle;
import org.apache.pdfbox.pdmodel.graphics.image.JPEGFactory;
import org.apache.pdfbox.pdmodel.graphics.image.PDImageXObject;
import org.apache.pdfbox.rendering.ImageType;
import org.apache.pdfbox.rendering.PDFRenderer;

import com.sga.tc.gs30.ccd.TrustCertCodeVO;
import com.sga.tc.gs30.pdf.CertCodePdf;
import com.sga.tc.gs30.util.UsingProperties;

import sepoa.fw.cache.Cache;
import sepoa.fw.cfg.Configuration;
import sepoa.fw.log.Logger;
import sepoa.fw.ses.SepoaInfo;
import sepoa.fw.srv.Description;
import sepoa.fw.srv.SepoaOut;
import sepoa.fw.srv.SepoaService;
import sepoa.fw.srv.SepoaServiceException;
import sepoa.fw.srv.module.SepoaModuleService;
import sepoa.fw.util.CommonUtil;
import sepoa.fw.util.renderer.SepoaPDFRenderer;
import sepoa.fw.util.renderer.image.SepoaImageCapture;
import sepoa.fw.util.renderer.image.SepoaImageCapture.Data;
import sepoa.fw.util.renderer.image.SepoaImageCapture.Engine;

@Description("날인요청 후처리 프로세서")
public class SepoaSealPostProcessor extends SepoaService{
	public SepoaSealPostProcessor(String opt, SepoaInfo info) throws SepoaServiceException {
		super(opt, info);
		setVersion("1.0.0");
	}
	
	@Description("SECL 날인요청 후처리 프로세스")
	public SepoaOut doProcess(Map<String, Object> data) {
		setStatus(1);
		setFlag(true);
		
		try {
			String orgFilePath = (String) data.get("PATH");
			File orgFile = new File(orgFilePath);
			
			/* SECL DBG */ 
			if("TRUE".equalsIgnoreCase(CommonUtil.getConfig("sepoa.server.development.flag", "false"))) {
				if(new File("C:/sepoa/restutil-log/"+data.get("SMR_NUMBER")).exists()) {
					FileUtils.forceMkdir(new File("C:/sepoa/restutil-log/"+data.get("SMR_NUMBER")));
				}
				FileUtils.copyFile(orgFile, new File("C:/sepoa/restutil-log/"+data.get("SMR_NUMBER")+"/"+"orgFile.pdf"));
			}
			
			if(!orgFile.exists()) {
				setStatus(104001);
				throw new Exception("Not Found Req Seal Document File!");
			}
			
			String resizeFilePath = orgFile.getParent() + File.separator + orgFile.getName() + "_" + System.nanoTime() + "_resize";
			float resizeScale = Float.parseFloat(CommonUtil.getConfig("sepoa.secl.sga.resize.scale", "0.9f"));
			resize(orgFilePath, resizeFilePath, resizeScale);
			
			/* SECL DBG */ 
			if("TRUE".equalsIgnoreCase(CommonUtil.getConfig("sepoa.server.development.flag", "false"))) {
				FileUtils.copyFile(new File(resizeFilePath), new File("C:/sepoa/restutil-log/"+data.get("SMR_NUMBER")+"/"+"resize.pdf"));
				
			}
			String barcodeMergeFilePath = orgFile.getParent() + File.separator + orgFile.getName() + "_" + System.nanoTime() + "_barcode";
			
			String strPath = CommonUtil.getConfig("sepoa.secl.sga.cert.path");
			UsingProperties.getInstance(strPath);
			CertCodePdf ccp = new CertCodePdf();
			TrustCertCodeVO vo = new TrustCertCodeVO(resizeFilePath, data.get("SMR_NUMBER")+"_"+data.get("SMD_NUMBER"), MapUtils.getString(data, "FILE_NAME_CLIENT", ""));
			vo.setWaterMark(true);
			vo.setWmXaxis(85);
		    vo.setWmYaxis(25);
		    vo.setResultPdfPath(barcodeMergeFilePath);
		    
			if(!ccp.applyMspCertCode(vo)) {
				setStatus(104002);
				throw new Exception("Barcode Document create Fail!" + vo);
			} else {
				if("TRUE".equalsIgnoreCase(CommonUtil.getConfig("sepoa.server.development.flag", "false"))) {
					/* SECL DBG */ 
					FileUtils.copyFile(new File(barcodeMergeFilePath), new File("C:/sepoa/restutil-log/"+data.get("SMR_NUMBER")+"/"+"barcode.pdf"));
				}
				
				SepoaPDFRenderer renderer = new SepoaPDFRenderer(new File(barcodeMergeFilePath));
				PDDocument doc = renderer.getPDFDoc();
				Map<Integer, String> fixHtmlMap = new HashMap<>();
				String imageBase64 = "data:image/png;base64,";
				for(int i = 0; i < doc.getNumberOfPages(); i++) {
					String pagTotalNo = (i+1) + "/" + doc.getNumberOfPages();
					String publishText = Cache.text.get("FOOTER_TEXT.PUB_NO") + " : " + data.get("PUBLISH_NO");
					String publishNoHtml = "<div style=\"position:absolute;bottom:27px;left:15px;border:solid 1px #000; width:60px; height:60px; background-size:cover; background-repeat:no-repeat; background-image:url(${IMAGE_BASE_64});\"></div>";
					publishNoHtml += "<div class=\"footer\" style=\"position:absolute;bottom:0px;width:100%;font-size:10px;z-index:100;display:flex;justify-content:left;text-align:left;\"><div style=\"padding:10px;color:#999;\">"+publishText+"</div></div>";
					publishNoHtml +="<div class=\"footer\" style=\"position:absolute;bottom:0px;width:100%;font-size:10px;z-index:100;display:flex;justify-content:right;text-align:center;\"><div style=\"padding:10px;color:#999;\">"+pagTotalNo+"</div></div>";
					publishNoHtml = publishNoHtml.replace("${IMAGE_BASE_64}", imageBase64);
					
					fixHtmlMap.put(i, publishNoHtml);
				}
				
				Map<Integer, Map<Data, String>> fixHtmlData = new HashMap<>();
				for(Entry<Integer, String> html : fixHtmlMap.entrySet()) {
					Map<Data, String> fixhtml = new HashMap<>();
					fixhtml.put(SepoaImageCapture.Data.HTML, html.getValue());
					
					PDRectangle cropBox = doc.getPage(html.getKey()).getCropBox();
					fixhtml.put(SepoaImageCapture.Data.WIDTH, String.valueOf(cropBox.getWidth()));
					fixhtml.put(SepoaImageCapture.Data.HEIGHT, String.valueOf(cropBox.getHeight()));
					fixHtmlData.put(html.getKey(), fixhtml);
				}
				
				SepoaImageCapture capture = new SepoaImageCapture();
				capture.setTempDirectory(orgFile.getParent() + "/temp/" + data.get("SMR_NUMBER")+ "/" +data.get("SMD_NUMBER") );
				capture.setEngine(Engine.CHROME);
				capture.setData(fixHtmlData);
				
				File fixFooterFile = renderer.render(capture.capture()).getAbsoluteFile();
				if("TRUE".equalsIgnoreCase(CommonUtil.getConfig("sepoa.server.development.flag", "false"))) {
					/* SECL DBG */ 
					FileUtils.copyFile(fixFooterFile, new File("C:/sepoa/restutil-log/"+data.get("SMR_NUMBER")+"/"+"fix_footer.pdf"));
				}
				
				data.put("PATH", fixFooterFile.getAbsolutePath());
				data.put("FILE_NAME_SERVER", new File(barcodeMergeFilePath).getName());
				Logger.info.println("Barcode Document Create Success" + data.get("SMR_NUMBER")+"_"+data.get("SMD_NUMBER"));
				
				FileUtils.forceDelete(new File(resizeFilePath));
			}
		} catch (Exception e) {
			if(getStatus() == 1) setStatus(0);
			e.printStackTrace();
			setFlag(false);
			setMessage(e.toString());
			Logger.err.println(info.getSession("ID"), this, e);
		}
		
		return getSepoaOut();
	}
	
	private void resize(String inFilePath, String outFilePath, float scale) throws Exception {
		PDDocument inDocument = PDDocument.load(new File(inFilePath));
		PDDocument pdDocument = new PDDocument();
		PDFRenderer pdfRenderer = new PDFRenderer(inDocument);
		int numberOfPages = inDocument.getNumberOfPages();
		PDPage page = null;

		for (int i = 0; i < numberOfPages; i++) {

			page = new PDPage(PDRectangle.LETTER);
			BufferedImage bim = pdfRenderer.renderImageWithDPI(i, 300, ImageType.RGB);
			PDImageXObject pdImage = JPEGFactory.createFromImage(pdDocument, bim);
			PDPageContentStream contentStream = new PDPageContentStream(pdDocument, page);

			float height = PDRectangle.LETTER.getHeight();
			float width = PDRectangle.LETTER.getWidth();
			float newHeight = height * scale;
			float newWidth = width * scale;

			float startX = (width - newWidth) / 2;
			float startY = height - newHeight;

			contentStream.drawImage(pdImage, startX, startY, newWidth, newHeight);
			contentStream.close();

			pdDocument.addPage(page);
		}

		pdDocument.save(outFilePath);
		pdDocument.close();
	}
	
}
